              <label class="choice"><input type="checkbox" name="q1" value="JavaScript"><span class="choice-text">JavaScript</span></label>
              <label class="choice"><input type="checkbox" name="q1" value="Sass"><span class="choice-text">Sass</span></label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>2. Which of these are commonly compiled programming languages?</legend>
            <div class="choices">
